				save.setAmendId(amendId);
				save.setLoginId(savedLBReq.getLoginId());
				save.setAgencyCode(savedLBReq.getAgencyCode() );
				save.setOaCode(savedLBReq.getOaCode());
				save.setOaCode(amendId);
